package pkg023

// Func023_00_00 is a deterministically generated function
// for the repomap perf fixture; it references Func024_01_00
// so the pagerank/refs step in repomap.Build has real edges
// to walk, not an isolated file per symbol.
func Func023_00_00(a, b int) int {
	if a > b {
		return Func024_01_00(a, b) + a
	}
	return Func024_01_00(b, a) - b
}

